update pages set contenu = '{"gabarit":"fiche","chapeau":"EATON a sollicité Migen en janvier 2023, au moment de l''installation d''un nouveau parc machine sur son site automobile. La demande portait sur un soutien technique à l''intégration, puis à la mise en production de ces outils.","fiche":[],"contexte":"**Un parc machine neuf ne produit pas le jour où il arrive sur le quai.** Il produit le jour où quelqu''un sait le régler, le dépanner et le tenir.\nUne mise en production concentre tous les risques industriels au même moment :\n**Des machines neuves à intégrer**, livrées et installées dans un calendrier contraint.\n**Aucun historique de panne** sur lequel s''appuyer pour anticiper les défaillances.\n**Des compétences variées attendues au même instant** : mécanique, électricité, automatisme.\n**Un préventif à construire** pendant que le curatif tourne déjà.","intervention":"**Une équipe constituée pour le projet** : 6 techniciens multidisciplinaires réunis pour couvrir l''ensemble du périmètre du nouveau parc.\n**L''accompagnement des livraisons** : Les techniciens Migen ont suivi l''arrivée et le montage des différentes machines.\n**La maintenance préventive du parc neuf** : Le plan d''entretien tourne dès la mise en service, sans attendre les premières casses.\n**La maintenance curative** : Les défaillances des premières semaines sont traitées sur place, par des techniciens qui connaissent déjà les machines.\n**Une équipe qui reste après le démarrage** : La connaissance machine acquise pendant l''installation ne repart pas avec le chantier.","resultats":[]}'::jsonb where path = '/preuves/eaton-mise-en-production/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"EATON, site automobile"},{"libelle":"Période","valeur":"Depuis janvier 2023, mission en cours"},{"libelle":"Déclencheur","valeur":"Installation d''un nouveau parc machine"},{"libelle":"Périmètre","valeur":"Intégration, mise en production, maintenance préventive et curative"},{"libelle":"Effectif Migen","valeur":"6 techniciens multidisciplinaires"},{"libelle":"Rôle de Migen","valeur":"Soutien technique à l''intégration, puis continuité opérationnelle"}]'::jsonb) where path = '/preuves/eaton-mise-en-production/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Un démarrage tenu","libelle":"Sans recruter six personnes dans l''urgence."},{"valeur":"Une connaissance machine conservée","libelle":"L''équipe reste après la mise en service."},{"valeur":"Un seul interlocuteur","libelle":"Pour le préventif, le curatif et l''accompagnement des installations."}]'::jsonb) where path = '/preuves/eaton-mise-en-production/';
